import{_ as t,o,c as i,a0 as a}from"./chunks/framework.Obqu-B4P.js";const y=JSON.parse('{"title":"Crypto model","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/crypto-model.md","filePath":"explanation/crypto-model.md"}'),r={name:"explanation/crypto-model.md"};function s(n,e,c,d,l,h){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="crypto-model" tabindex="-1">Crypto model <a class="header-anchor" href="#crypto-model" aria-label="Permalink to &quot;Crypto model&quot;">​</a></h1><p>One crypto choice everywhere, made once in ADR-0001: <strong>age</strong>. Every vault impl stores age ciphertext; the same identity unlocks the local file vault and the remote <code>cf</code> vault alike.</p><h2 id="the-pieces" tabindex="-1">The pieces <a class="header-anchor" href="#the-pieces" aria-label="Permalink to &quot;The pieces&quot;">​</a></h2><ul><li><strong>Identity</strong> — one X25519 keypair, held by an <code>cuora-identity</code> impl (ADR-0002): the <strong>session keyring</strong> (secret-service, macOS Keychain, Credential Manager) by default — fail closed — or the <code>~/.config/cuora/identity.txt</code> keyfile (mode <code>0600</code>) under <code>auto</code>/<code>file</code> modes or an explicit pin. An explicit file — <code>CUORA_IDENTITY_FILE</code> or <code>[vaults.*].identity</code> — pins the keyfile outright; that is the headless/CI path. <code>[identity] backend</code> (or <code>CUORA_IDENTITY_BACKEND</code>) selects the mode: <code>keyring</code> (default) fails closed — no reachable store or stored identity is an error, the keyfile is never read; <code>auto</code> is the fallback described above — convenient on headless/CI, but a <em>silent</em> downgrade if a desktop session loses its store, so it&#39;s opt-in; <code>file</code> skips the store probe entirely. <code>cuora init</code> bootstraps whichever backend applies and prints the public <code>age1…</code> recipient. On a reachable-but-empty Secret Service (fresh daemon, no collections yet) the keyring impl claims the <code>default</code> collection alias on first use — <code>dbus-secret-service-keyring-store</code>&#39;s create path can&#39;t bootstrap one itself (I-006).</li><li><strong>Recipients</strong> — <code>[vaults.*].recipients</code> encrypts to extra public keys beyond the identity&#39;s own — a team recipient list without sharing the private key.</li><li><strong>Ciphertext at rest</strong> — the local vault is a single age-encrypted file (<code>vault.age</code>); the <code>cf</code> vault stores per-secret age ciphertext in D1. Neither store — local disk, remote worker — holds plaintext or key material.</li><li><strong>Seal/open at the edge</strong> — values are plaintext only inside the cuora process, and only for as long as the op needs them. <code>Secret</code> is a <code>Zeroizing</code> newtype: memory is scrubbed on drop, and nothing but <code>.expose()</code> reads it.</li><li><strong>HMAC alongside age</strong> — the <code>cf</code> wire uses HMAC-SHA256 twice (P-003, P-004), keyed but unkeyed-payload, complementary to the age envelope: request <em>signing</em> so tokens never travel, and <code>ref_key</code> <em>derivation</em> so storage keys are unlinkable. Neither is a second encryption primitive — it&#39;s authentication and deterministic naming.</li></ul><h2 id="why-age-and-not-kms-libsodium-ssh-keys" tabindex="-1">Why age (and not KMS / libsodium / SSH keys) <a class="header-anchor" href="#why-age-and-not-kms-libsodium-ssh-keys" aria-label="Permalink to &quot;Why age (and not KMS / libsodium / SSH keys)&quot;">​</a></h2><ul><li><strong>One identity, every backend</strong> — a remote vault that stores client-side ciphertext needs an offline asymmetric primitive; age gives recipient-style encryption with no service to trust.</li><li><strong>Dependency posture</strong> — the <code>age</code> crate (rage&#39;s Rust impl) is pulled with <code>default-features = false</code>: binary ciphertext, sync API, no async/armor/plugin machinery — the binary stays light per the workspace rules.</li><li><strong>Interop for free</strong> — the vault file decrypts with stock <code>rage</code>/<code>age</code> tooling, so a human is never locked into the CLI for disaster recovery.</li></ul><h2 id="the-cf-wire-cuora-vault-cf-2" tabindex="-1">The cf wire (<code>cuora-vault-cf/2</code>) <a class="header-anchor" href="#the-cf-wire-cuora-vault-cf-2" aria-label="Permalink to &quot;The cf wire (`cuora-vault-cf/2`)&quot;">​</a></h2><ul><li><strong>Request signing</strong> — <code>Authorization: CuoraHmac &amp;lt;token_id&amp;gt;, &amp;lt;ts&amp;gt;, &amp;lt;sig&amp;gt;</code> with <code>sig = hex HMAC-SHA256(token, method+path+ts+ sha256hex(body))</code>. The token is the HMAC key and never crosses the wire; a ±60s timestamp window bounds replay. Worker-side, <code>CUORA_VAULT_TOKENS</code> maps <code>token_id → {env → {read, write}}</code> scopes — per-env credentials instead of one static bearer (which stays accepted during migration).</li><li><strong>Private refs</strong> — with <code>[vaults.*] private_refs = true</code>, the storage key is <code>ref_key = hex HMAC-SHA256(k, env + &quot;/&quot; + ref)</code> where <code>k = HMAC-SHA256(identity, &quot;cuora-cf/private-refs/v1&quot;)</code>. Derivation is deterministic (lookup is a plain keyed read) and identity-bound (rotating the identity re-keys everything, via <code>cuora migrate --private-refs</code>). The real ref travels inside a <code>name</code> blob — age ciphertext — so <code>list</code> maps keys back while the store sees only hex.</li><li><strong>Constant-time compares</strong> — every token/signature comparison on the worker is a byte-wise XOR-fold over the longer input with length folded in; no early exit, no prefix oracle.</li></ul><h2 id="what-is-deliberately-not-here" tabindex="-1">What is deliberately not here <a class="header-anchor" href="#what-is-deliberately-not-here" aria-label="Permalink to &quot;What is deliberately not here&quot;">​</a></h2><ul><li><strong>No KMS port yet</strong> — managed-key backends (AWS KMS/Secrets Manager) were explored in the <code>cuora-vault-aws</code> spike to prove the <code>Vault</code> port generalizes to non-age stores; a KMS-backed <em>crypto</em> port is a later ADR, not v1.</li><li><strong>No passphrase-wrapped identity file</strong> — when the keyring is unavailable the keyfile is still raw age key material at <code>0600</code>, like an unencrypted SSH key. A passphrase-wrapped arm of the identity port is a later impl, not a new port.</li><li><strong>No signing / integrity metadata</strong> beyond what age&#39;s AEAD gives — tampered ciphertext fails decryption loudly, which is the correct failure.</li></ul>',10)])])}const u=t(r,[["render",s]]);export{y as __pageData,u as default};
